#ifndef ZOVUTILS_STAT_BACKEND_H
#define ZOVUTILS_STAT_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pwd.h>
#include <grp.h>
#include <time.h>
static inline const char*zov_stat_type(mode_t m){return S_ISREG(m)?"regular file":S_ISDIR(m)?"directory":S_ISLNK(m)?"symbolic link":S_ISFIFO(m)?"fifo":S_ISSOCK(m)?"socket":S_ISCHR(m)?"character special file":S_ISBLK(m)?"block special file":"unknown file type";}
static inline void zov_stat_format(const char*f,const char*name,const struct stat*s,int newline){char b[64];for(size_t i=0;f[i];i++){if(f[i]=='\\'&&f[i+1]){char c=f[++i];if(c=='n')putchar('\n');else if(c=='t')putchar('\t');else if(c=='\\')putchar('\\');else{putchar('\\');putchar(c);}continue;}if(f[i]!='%'){putchar(f[i]);continue;}char c=f[++i];if(!c)break;switch(c){case '%':putchar('%');break;case 'n':fputs(name,stdout);break;case 'N':printf("'%s'",name);break;case 's':printf("%lld",(long long)s->st_size);break;case 'b':printf("%lld",(long long)s->st_blocks);break;case 'B':printf("%ld",(long)s->st_blksize);break;case 'i':printf("%llu",(unsigned long long)s->st_ino);break;case 'h':printf("%lu",(unsigned long)s->st_nlink);break;case 'u':printf("%lu",(unsigned long)s->st_uid);break;case 'g':printf("%lu",(unsigned long)s->st_gid);break;case 'U':{struct passwd*p=getpwuid(s->st_uid);if(p)fputs(p->pw_name,stdout);else printf("%lu",(unsigned long)s->st_uid);break;}case 'G':{struct group*p=getgrgid(s->st_gid);if(p)fputs(p->gr_name,stdout);else printf("%lu",(unsigned long)s->st_gid);break;}case 'a':printf("%o",(unsigned)(s->st_mode&07777));break;case 'A':{const char*q="rwxrwxrwx";for(int j=0;j<9;j++)putchar((s->st_mode&(1<<(8-j)))?q[j]:'-');break;}case 'd':printf("%llu",(unsigned long long)s->st_dev);break;case 'F':fputs(zov_stat_type(s->st_mode),stdout);break;case 'x':case 'y':case 'z':{time_t t=c=='x'?s->st_atime:c=='y'?s->st_mtime:s->st_ctime;struct tm tmv;localtime_r(&t,&tmv);strftime(b,sizeof b,"%Y-%m-%d %H:%M:%S",&tmv);printf("%s.%09ld %s",b,(long)(c=='x'?0:0),"+0000");break;}default:putchar('%');putchar(c);break;}}if(newline)putchar('\n');}
static inline int zov_stat_run(int argc,char**argv){const char*format=NULL;int follow=0,printfmode=0,nf=0;char**files=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: stat [OPTION]... FILE...\nDisplay file or file system status.\n  -L, --dereference     follow links\n  -c, --format=FORMAT   use the specified FORMAT instead of the default\n  --printf=FORMAT       like --format, but interpret backslash escapes and\n                          do not output a mandatory trailing newline\n      --help            display this help and exit\n      --version         output version information and exit");free(files);return 0;}if(!strcmp(a,"--version")){puts("stat (zovutils) 0.10.19");free(files);return 0;}if(!strcmp(a,"-L")||!strcmp(a,"--dereference")){follow=1;continue;}if(!strcmp(a,"-c")||!strcmp(a,"--format")||!strcmp(a,"--printf")){if(i+1>=argc){fprintf(stderr,"stat: option requires an argument -- 'c'\n");free(files);return 1;}format=argv[++i];printfmode=!strcmp(a,"--printf");continue;}if(!strncmp(a,"--format=",9)){format=a+9;continue;}if(!strncmp(a,"--printf=",9)){format=a+9;printfmode=1;continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"stat: unrecognized option '%s'\nTry 'stat --help' for more information.\n",a);free(files);return 1;}files[nf++]=(char*)a;}if(!nf){fprintf(stderr,"stat: missing operand\nTry 'stat --help' for more information.\n");free(files);return 1;}if(!format)format="  File: %N\n  Size: %s\tBlocks: %b\tIO Block: %B\t%F\nDevice: %d\tInode: %i\tLinks: %h\nAccess: (%a/%A)\tUid: (%u/%U)\tGid: (%g/%G)\nAccess: %x\nModify: %y\nChange: %z\n";int status=0;for(int i=0;i<nf;i++){struct stat st;int rc=follow?stat(files[i],&st):lstat(files[i],&st);if(rc<0){fprintf(stderr,"stat: cannot stat '%s': %s\n",files[i],strerror(errno));status=1;continue;}zov_stat_format(format,files[i],&st,!printfmode);}free(files);return status;}
#endif
